mapper.select:
select tuca.id, tuca.card_level1, tuca.card_level2, tuca.card_level3,
tuca.card_level4, tuca.create_time,tui.nick_name nickName, tui.avatar avatar,
tui.user_code userCode from t_user_card_asset tuca
left join t_user_info tui on tuca.id = tui.user_id

     and tuca.card_level1 = #{cardLevel1}
     and tuca.card_level2 = #{cardLevel2}
     and tuca.card_level3 = #{cardLevel3}
     and tuca.card_level4 = #{cardLevel4}

     and tuca.create_time between #{params.beginCreateTime} and #{params.endCreateTime}

order by id desc
